mapper.select:
select count(1)
from spas_student_point_ledger
where student_id = #{studentId}
  and reason_code = #{reasonCode}
  and create_time::date = #{day}::date

  and subject_id = #{subjectId}

select ledger_id, student_id, dept_id, subject_id, points, reason_code, ref_type, ref_id,
       biz_key, remark, create_time
from spas_student_point_ledger
where student_id = #{studentId}
order by create_time desc, ledger_id desc
limit #{limit}

select rank_no from (
    select a.student_id,
           row_number() over (order by a.total_points desc, a.update_time asc, a.student_id) as rank_no
    from spas_student_point_account a
    join spas_student s on s.student_id = a.student_id
    where s.dept_id = #{deptId}
      and coalesce(s.status, '0') = '0'
      and a.total_points > 0
) t where t.student_id = #{studentId}

select rank_no from (
    select a.student_id,
           row_number() over (order by a.week_points desc, a.update_time asc, a.student_id) as rank_no
    from spas_student_point_account a
    join spas_student s on s.student_id = a.student_id
    where s.dept_id = #{deptId}
      and coalesce(s.status, '0') = '0'
      and a.week_start = #{weekStart}::date
      and a.week_points > 0
) t where t.student_id = #{studentId}
